#include "include/CaptureBridge.h"
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <stdint.h>
#define AUDIO_RATE 48000
#define AUDIO_CHANNELS 2
#define AUDIO_CAPACITY (AUDIO_RATE*2)
struct VelaRawSource {pthread_mutex_t lock;pthread_cond_t ready;atomic_int refs;unsigned width,height;double fps;size_t bytes;unsigned char *latest;unsigned long sequence;int finished;int audio_enabled;float *audio;uint64_t audio_written;};
typedef struct Reader Reader;
struct VelaRawToken {VelaRawSource *source;atomic_int refs;atomic_int cancelled;uint64_t audio_cursor,audio_frames,video_frames;Reader*reader;};
struct Reader {VelaRawToken *token;unsigned char *frame;size_t offset;unsigned long sequence;int has_frame;struct timespec deadline;};
VelaRawSource *vela_raw_new(unsigned w,unsigned h,double fps){if(!w||!h||w>4096||h>2160||fps<1||fps>120)return NULL;VelaRawSource*s=calloc(1,sizeof(*s));if(!s)return NULL;s->width=w;s->height=h;s->fps=fps;s->bytes=(size_t)w*h*4;s->latest=malloc(s->bytes);if(!s->latest){free(s);return NULL;}pthread_mutex_init(&s->lock,NULL);pthread_cond_init(&s->ready,NULL);atomic_init(&s->refs,1);return s;}
void vela_raw_hold(VelaRawSource*s){if(s)atomic_fetch_add(&s->refs,1);}
void vela_raw_release(VelaRawSource*s){if(s&&atomic_fetch_sub(&s->refs,1)==1){pthread_cond_destroy(&s->ready);pthread_mutex_destroy(&s->lock);free(s->latest);free(s->audio);free(s);}}
void vela_raw_finish(VelaRawSource*s){if(!s)return;pthread_mutex_lock(&s->lock);s->finished=1;pthread_cond_broadcast(&s->ready);pthread_mutex_unlock(&s->lock);}
int vela_raw_push(VelaRawSource*s,const void*p,size_t stride){if(!s||!p||stride<(size_t)s->width*4)return-1;pthread_mutex_lock(&s->lock);if(s->finished){pthread_mutex_unlock(&s->lock);return-1;}for(unsigned y=0;y<s->height;y++)memcpy(s->latest+(size_t)y*s->width*4,(const unsigned char*)p+(size_t)y*stride,(size_t)s->width*4);s->sequence++;pthread_cond_broadcast(&s->ready);pthread_mutex_unlock(&s->lock);return 0;}
int vela_raw_enable_audio(VelaRawSource*s){if(!s)return-1;pthread_mutex_lock(&s->lock);if(!s->audio)s->audio=calloc(AUDIO_CAPACITY*AUDIO_CHANNELS,sizeof(float));s->audio_enabled=s->audio!=NULL;pthread_mutex_unlock(&s->lock);return s->audio_enabled?0:-1;}
int vela_raw_push_audio(VelaRawSource*s,const float*p,size_t frames){if(!s||!p||frames>AUDIO_CAPACITY)return-1;pthread_mutex_lock(&s->lock);if(!s->audio_enabled||s->finished){pthread_mutex_unlock(&s->lock);return-1;}for(size_t n=0;n<frames;n++){size_t target=(s->audio_written+n)%AUDIO_CAPACITY;memcpy(s->audio+target*AUDIO_CHANNELS,p+n*AUDIO_CHANNELS,AUDIO_CHANNELS*sizeof(float));}s->audio_written+=frames;pthread_cond_broadcast(&s->ready);pthread_mutex_unlock(&s->lock);return 0;}
static int audio_get(void*opaque,const char*cookie,int64_t*dts,int64_t*pts,unsigned*flags,size_t*size,void**data){VelaRawToken*t=opaque;if(!t&&cookie)t=(VelaRawToken*)(uintptr_t)strtoull(cookie,NULL,10);if(!t||!dts||!pts)return-1;VelaRawSource*s=t->source;if(atomic_load(&t->cancelled))return-1;float*output=calloc(480*AUDIO_CHANNELS,sizeof(float));if(!output)return-1;pthread_mutex_lock(&s->lock);if(s->finished||atomic_load(&t->cancelled)){pthread_mutex_unlock(&s->lock);free(output);return-1;}if(s->audio_written>t->audio_cursor+AUDIO_CAPACITY)t->audio_cursor=s->audio_written-AUDIO_CAPACITY;size_t count=s->audio_written-t->audio_cursor;if(count>480)count=480;for(size_t n=0;n<count;n++)memcpy(output+n*AUDIO_CHANNELS,s->audio+((t->audio_cursor+n)%AUDIO_CAPACITY)*AUDIO_CHANNELS,AUDIO_CHANNELS*sizeof(float));t->audio_cursor+=count;pthread_mutex_unlock(&s->lock);*dts=*pts=(int64_t)(t->audio_frames*1000000/AUDIO_RATE);t->audio_frames+=480;*flags=0;*size=480*AUDIO_CHANNELS*sizeof(float);*data=output;return 0;}
static void audio_release(void*opaque,const char*cookie,size_t size,void*data){(void)opaque;(void)cookie;(void)size;free(data);}
static void token_release(VelaRawToken*t){if(atomic_fetch_sub(&t->refs,1)==1){vela_raw_release(t->source);free(t);}}
static int open_input(void*opaque,void**data,uint64_t*size){VelaRawToken*t=opaque;if(atomic_load(&t->cancelled))return-1;Reader*r=calloc(1,sizeof(*r));if(!r)return-1;r->frame=malloc(t->source->bytes);if(!r->frame){free(r);return-1;}r->token=t;atomic_fetch_add(&t->refs,1);*data=r;*size=UINT64_MAX;return 0;}
static ssize_t read_input(void*opaque,unsigned char*buffer,size_t length){Reader*r=opaque;VelaRawToken*t=r->token;VelaRawSource*s=t->source;if(atomic_load(&t->cancelled))return 0;if(!r->has_frame||r->offset==s->bytes){pthread_mutex_lock(&s->lock);if(!r->has_frame){while(!s->sequence&&!s->finished&&!atomic_load(&t->cancelled))pthread_cond_wait(&s->ready,&s->lock);clock_gettime(CLOCK_REALTIME,&r->deadline);}else{r->deadline.tv_nsec+=(long)(1000000000/s->fps);while(r->deadline.tv_nsec>=1000000000){r->deadline.tv_nsec-=1000000000;r->deadline.tv_sec++;}struct timespec now;clock_gettime(CLOCK_REALTIME,&now);while((now.tv_sec<r->deadline.tv_sec||(now.tv_sec==r->deadline.tv_sec&&now.tv_nsec<r->deadline.tv_nsec))&&!s->finished&&!atomic_load(&t->cancelled)){pthread_cond_timedwait(&s->ready,&s->lock,&r->deadline);clock_gettime(CLOCK_REALTIME,&now);}if(now.tv_sec>r->deadline.tv_sec+1)r->deadline=now;}if(s->finished||atomic_load(&t->cancelled)){pthread_mutex_unlock(&s->lock);return 0;}memcpy(r->frame,s->latest,s->bytes);r->sequence=s->sequence;r->offset=0;r->has_frame=1;pthread_mutex_unlock(&s->lock);}size_t n=s->bytes-r->offset;if(n>length)n=length;memcpy(buffer,r->frame+r->offset,n);r->offset+=n;return(ssize_t)n;}
static void close_input(void*opaque){Reader*r=opaque;token_release(r->token);free(r->frame);free(r);}
static int capture_get(void*opaque,const char*cookie,int64_t*dts,int64_t*pts,unsigned*flags,size_t*size,void**data){(void)opaque;if(!cookie||!dts||!pts)return-1;VelaRawToken*t=(VelaRawToken*)(uintptr_t)strtoull(cookie+1,NULL,10);if(!t||atomic_load(&t->cancelled))return-1;if(cookie[0]=='a')return audio_get(t,NULL,dts,pts,flags,size,data);if(!t->reader){void*reader=NULL;uint64_t length;if(open_input(t,&reader,&length))return-1;t->reader=reader;}unsigned char*frame=malloc(t->source->bytes);if(!frame)return-1;ssize_t count=read_input(t->reader,frame,t->source->bytes);if(count<=0){free(frame);return-1;}*dts=*pts=(int64_t)(t->video_frames++*1000000/t->source->fps);*flags=0;*size=count;*data=frame;return 0;}
static void media_freed(const libvlc_event_t*event,void*opaque){(void)event;VelaRawToken*t=opaque;if(t->reader){close_input(t->reader);t->reader=NULL;}token_release(t);}
libvlc_media_t*vela_raw_media(libvlc_instance_t*i,VelaRawSource*s,VelaRawToken**out){
 if(!i||!s)return NULL;VelaRawToken*t=calloc(1,sizeof(*t));if(!t)return NULL;atomic_init(&t->refs,1);atomic_init(&t->cancelled,0);t->source=s;pthread_mutex_lock(&s->lock);t->audio_cursor=s->audio_written;pthread_mutex_unlock(&s->lock);vela_raw_hold(s);
 char location[256];snprintf(location,sizeof location,"imem://cat=2:codec=RV32:width=%u:height=%u:fps=%.3f:cookie=v%llu",s->width,s->height,s->fps,(unsigned long long)(uintptr_t)t);libvlc_media_t*m=libvlc_media_new_location(i,location);if(!m){token_release(t);return NULL;}
 libvlc_event_attach(libvlc_media_event_manager(m),libvlc_MediaFreed,media_freed,t);char option[120];snprintf(option,sizeof option,":imem-get=%llu",(unsigned long long)(uintptr_t)capture_get);libvlc_media_add_option_flag(m,option,libvlc_media_option_trusted);snprintf(option,sizeof option,":imem-release=%llu",(unsigned long long)(uintptr_t)audio_release);libvlc_media_add_option_flag(m,option,libvlc_media_option_trusted);libvlc_media_add_option(m,":live-caching=100");
 if(s->audio_enabled){char slave[180];snprintf(slave,sizeof slave,"imem://cat=1:codec=f32l:samplerate=48000:channels=2:cookie=a%llu",(unsigned long long)(uintptr_t)t);libvlc_media_slaves_add(m,libvlc_media_slave_type_audio,4,slave);}if(out)*out=t;return m;
}
void vela_raw_cancel(VelaRawToken*t){if(!t)return;atomic_store(&t->cancelled,1);pthread_mutex_lock(&t->source->lock);pthread_cond_broadcast(&t->source->ready);pthread_mutex_unlock(&t->source->lock);}
